"""TOEFL iBT 2026 Conversations & Academic Talks (Packs 1-3: 8 audio groups x 4 Qs = 32/pack)."""

from pack_schema_helpers import rotated_mcq


def expand_ibt_listening_groups(pack_num: int, groups: list) -> list[dict]:
    items = []
    q_idx = 66
    assert len(groups) == 8, f"Pack {pack_num} needs 8 listening talk/conv groups"
    for grp_id, label, turns, qs in groups:
        assert len(qs) == 4, f"{grp_id}: expected 4 questions"
        aid = f"IBT0{pack_num}-{grp_id}"
        for sub_i, (qtext, opts, cidx, mod, diff, exp) in enumerate(qs, start=1):
            qid = f"IBT26-0{pack_num}-Q{q_idx:03d}"
            items.append(
                rotated_mcq(
                    qid=qid,
                    section="LISTENING",
                    prompt=f"{label} — Item {sub_i}/4: {qtext}",
                    options=opts,
                    correct_idx=cidx,
                    explanation=exp,
                    rationale_source=mod,
                    difficulty=diff,
                    seed=pack_num * 29 + q_idx,
                    audio_id=aid,
                    audio_turns=turns if sub_i == 1 else [],
                ),
            )
            q_idx += 1
    assert len(items) == 32
    return items


